INSERT INTO `cy_config` VALUES ('15', '1', '--1', '备案信息', 'web_Copyright', '<a class=\"ico-ico\" href=\"http://beian.miit.gov.cn/\" rel=\"nofollow\" target=\"_blank\" title=\"桂ICP备2021006345号\">                                    <img src=\"/images/beian.png\" alt=\"桂ICP备2021006345号\">桂ICP备2021006345号                                </a>                                <span class=\"rt-times\">运行时长：0.052秒</span>                                ', '100', '模板调用{$Think.config.web.web_Copyright}', 'textarea');
INSERT INTO `cy_config` VALUES ('16', '1', '--1', '版本信息', 'web_Copy', 'Copyright<i class=\"fa fa-copyright\"></i>                                2015-2019<a href=\"/\">站长自主搭建</a>                                版权所有. 基于<a href=\"http://www.889mi.com/\" rel=\"nofollow\" title=\"889mi\" target=\"_blank\">889mi</a>                                搭建 安全运行<span id=\"iday\">5518</span>天\r\n<p id=\"RunTime\"></p>\r\n<script>\r\nvar myVar=setInterval(function(){myTimer()},1000);\r\nfunction myTimer(){\r\n	var d=new Date();\r\n	var t=d.toLocaleTimeString();\r\n	var dangqian = d.getFullYear() + \"-\" + (d.getMonth() + 1) + \"-\" + d.getDate() ;\r\n	document.getElementById(\"RunTime\").innerHTML=\"已经勉强运行：\"+ DateDiff(\"2010-08-1\",dangqian) +\" 天:\" + t;\r\n}\r\n/* 计算运行天数的封装函数 */\r\nfunction  DateDiff(sDate1,  sDate2){    //sDate1和sDate2是2002-12-18格式  \r\n  var  aDate,  oDate1,  oDate2,  iDays  \r\n  aDate  =  sDate1.split(\"-\")  \r\n  oDate1  =  new  Date(aDate[1]  +  \'-\'  +  aDate[2]  +  \'-\'  +  aDate[0])    //转换为12-18-2002格式  \r\n  aDate  =  sDate2.split(\"-\")  \r\n  oDate2  =  new  Date(aDate[1]  +  \'-\'  +  aDate[2]  +  \'-\'  +  aDate[0])  \r\n  iDays  =  parseInt(Math.abs(oDate1  -  oDate2)  /  1000  /  60  /  60  /24)    //把相差的毫秒数转换为天数  \r\n  return  iDays  \r\n}\r\n</script>', '100', '模板调用{$Think.config.web.web_Copy}', 'textarea');
